import{z as l,x as B,o as t,c as p,q as n,j as s,D as o,d as e,s as A,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"不完全市场 GEI","description":"","frontmatter":{"title":"不完全市场 GEI","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/incomplete-markets-gei.md","filePath":"econ/incomplete-markets-gei.md","lastUpdated":1791063341000}'),m={name:"econ/incomplete-markets-gei.md"};function d(D,E,c,h,C,u){const r=B("Mermaid");return t(),p("div",null,[E[2]||(E[2]=n('<h1 id="不完全市场-gei" tabindex="-1">不完全市场 GEI <a class="header-anchor" href="#不完全市场-gei" aria-label="Permalink to &quot;不完全市场 GEI&quot;">​</a></h1><div class="epigraph"><p>资产张成不足时，竞争配置不必帕累托有效；名义资产还让均衡的实变量可以不确定。</p><footer>—— 据 Magill and Quinzii, Theory of Incomplete Markets, 1996；Geanakoplos, An Introduction to General Equilibrium with Incomplete Asset Markets, JME, 1990 整理</footer></div><p>定位：<a href="/econ/core-equivalence">上一课</a>。复制使核缩到瓦尔拉斯配置，故事默认商品空间列全、Arrow 证券张成全部状态。<a href="/econ/state-contingent">状态依存</a>已钉完全市场那一端。本课不重写 Debreu–Scarf 的分离。缺口是张成不足：只有 \\(J\\lt S\\) 种资产，现货与证券两层价格，均衡不必有效，名义单位可以留下实不确定性。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>两期，\\(S\\) 个未到状态。0 期交易资产，收益矩阵 \\(A\\) 为 \\(S\\times J\\)，1 期现货市场再开。GEI 均衡是资产价格 \\(q\\)、现货 \\(p=(p_s)\\)、持仓与现货消费，使证券与现货同时出清，每人在预算下最优。完全当 \\(\\mathrm{span}(A)=\\mathbb{R}^S\\)（可允许 \\(A\\) 随 \\(p\\) 变的实资产）。不完全当可及的或有转移是 \\(A\\) 的列空间的真子空间。缺口不是再定义一次瓦尔拉斯，而是：<strong>缺列的时候，第一福利定理哪一步破，价格水平还定不定。</strong></p><p><span class="marginnote">「张成」翻译成人话：能用现有资产拼出多少种「在不同状态之间搬钱」的方式。每种资产贡献一根列，未来有 \\(S\\) 种状态要搬钱，资产却只有 \\(J\\lt S\\) 根——总有几种搬法拼不出来，那几块就是这张资产菜单保不了的风险。</span></p><p>核等价把「人多」变成竞争；它不填补缺掉的状态证券。联盟即使用自己的禀赋，也只能用现有资产重新分担风险，不能凭空创造缺的 Arrow 证券。故不完全市场的核与均衡都相对于<strong>受约束</strong>的可行集，不是相对于完全市场的帕累托集。</p><h3 id="约束有效不是有效" tabindex="-1">约束有效不是有效 <a class="header-anchor" href="#约束有效不是有效" aria-label="Permalink to &quot;约束有效不是有效&quot;">​</a></h3><p>Geanakoplos–Polemarchakis：即便只允许用现有资产再交易，GEI 均衡一般仍不是约束帕累托有效——现货价格把资产的实际收益内生化，单个人不内部化自己持仓对他人跨状态预算的影响。完全市场没有这层金钱外部性，因为任何转移都能直接买到。不要把「缺市场」读成「均衡在约束集里还有效」。</p><p><span class="marginnote">名义资产用货币单位承诺支付；现货价格一变，实际收益 \\(A\\) 的列跟着变。Cass 指出：名义资产下均衡配置可以有高维不确定性。实资产（商品单位支付）通常局部确定。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>定义预算：0 期 \\(p_0\\cdot(x_0-\\omega_0)+q\\cdot\\phi=0\\)；状态 \\(s\\) 有 \\(p_s\\cdot(x_s-\\omega_s)=p_s\\cdot A_s\\phi\\)（实资产则右端不依赖 \\(p_s\\) 的水平）。均衡要求 \\(\\sum\\phi=0\\)、各现货出清。存在性比 Arrow–Debreu 脆：卖空无界、收益矩阵掉秩，需要截断或 numéraire 资产约定。本课不把存在当成定理目标，只钉张成与福利。</p><p>完全化：若能对每个 \\(s\\) 添 Arrow 证券，回到<a href="/econ/state-contingent">状态依存</a>的第一优。公司证券、期权能否张成，取决于现货价格是否把收益变得线性独立——内生张成是边界，主干先当 \\(A\\) 外生。</p><p>无套利给张成空间里的收益一个线性定价泛函；张成之外只有价格区间，不能把任意或有束标成唯一的 \\(q\\)。</p>',14)),(t(),s(i,null,{default:o(()=>[A(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20AD%5B%22%E5%AE%8C%E5%85%A8%EF%BC%9Aspan%20%3D%20R%5ES%EF%BC%8C%E5%B8%95%E7%B4%AF%E6%89%98%22%5D%20--%3E%20GEI%5B%22J%20%EF%BC%9C%20S%EF%BC%9A%E5%BC%A0%E6%88%90%E4%B8%8D%E8%B6%B3%22%5D%0A%20%20GEI%20--%3E%20WEL%5B%22%E5%9D%87%E8%A1%A1%E4%B8%8D%E5%BF%85%E5%B8%95%E7%B4%AF%E6%89%98%EF%BC%8C%E7%94%9A%E8%87%B3%E4%B8%8D%E5%BF%85%E7%BA%A6%E6%9D%9F%E6%9C%89%E6%95%88%22%5D%0A%20%20GEI%20--%3E%20NOM%5B%22%E5%90%8D%E4%B9%89%E8%B5%84%E4%BA%A7%EF%BC%9A%E5%AE%9E%E9%99%85%E9%85%8D%E7%BD%AE%E5%8F%AF%E4%B8%8D%E5%AE%9A%22%5D%0A%20%20GEI%20--%3E%20REAL%5B%22%E5%AE%9E%E8%B5%84%E4%BA%A7%EF%BC%9A%E9%80%9A%E5%B8%B8%E5%B1%80%E9%83%A8%E7%A1%AE%E5%AE%9A%22%5D%0A"})]),fallback:o(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("p",null,"不要把资产张成写成限价簿的档位深度。GEI 仍是瓦尔拉斯式出清，没有队列；缺的是列，不是流动性协议。",-1)),E[4]||(E[4]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[5]||(E[5]=a("p",null,[e("第一定理失败的机制是：帕累托改进可能要求一种「只在某 \\(s\\) 转移」的方向，而 \\(\\mathrm{span}(A)\\) 里没有这个方向。约束无效的机制是金钱外部性：\\(i\\) 改 \\(\\phi\\) 会改某些 \\(p_s\\)，从而改 \\(A\\) 对 \\(k\\) 的实际购买力，\\(i\\) 不计入。名义不定的机制是：0 期把名义单位乘 \\(\\lambda\\)，1 期现货价格可以同比缩放，实际消费与相对价格的方程组少了锚——与"),a("a",{href:"/econ/walras-law-numeraire"},"计价物"),e("课「必须选正价格商品当锚」是同一类会计，但这里缺的锚在未到状态之间。")],-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"名义资产的实不确定可以类比「承诺到期还你一万张钞票」的借条：钞票将来值多少钱没人锁死，物价走到哪，这张借条的实际购买力就跟到哪——所以均衡可以有好几个，差别只在未来物价，不在任何真实技术。")],-1)),(t(),s(i,null,{default:o(()=>[A(r,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20WANT%5B%22%E5%B8%95%E7%B4%AF%E6%89%98%E6%94%B9%E8%BF%9B%E6%96%B9%E5%90%91%3A%20%E5%8F%AA%E5%9C%A8%E7%8A%B6%E6%80%81%20s%20%E8%BD%AC%E7%A7%BB%22%5D%20--%3E%20SPAN%7B%22%E6%96%B9%E5%90%91%E5%9C%A8%20span(A)%20%E9%87%8C%E5%90%97%3F%22%7D%0A%20%20SPAN%20--%3E%7C%22%E5%9C%A8%22%7C%20OK%5B%22%E7%94%A8%E7%8E%B0%E6%9C%89%E8%B5%84%E4%BA%A7%E5%AE%9E%E7%8E%B0%2C%20%E6%94%B9%E8%BF%9B%E5%8F%AF%E8%A1%8C%22%5D%0A%20%20SPAN%20--%3E%7C%22%E4%B8%8D%E5%9C%A8%3A%20%E7%BC%BA%E9%82%A3%E6%A0%B9%E5%88%97%22%7C%20NO%5B%22%E6%94%B9%E8%BF%9B%E6%97%A0%E6%B3%95%E4%BA%A4%E6%98%93%2C%20%E5%8D%A1%E5%9C%A8%E5%8E%9F%E5%9C%B0%22%5D%0A%20%20NO%20--%3E%20MONEY%5B%22%E9%87%91%E9%92%B1%E5%A4%96%E9%83%A8%E6%80%A7%3A%20%E6%8C%81%E4%BB%93%E6%94%B9%E5%8F%98%E7%8E%B0%E8%B4%A7%E4%BB%B7%22%5D%0A%20%20MONEY%20--%3E%20CEV%5B%22%E8%BF%9E%E7%BA%A6%E6%9D%9F%E6%9C%89%E6%95%88%E4%B9%9F%E4%BF%9D%E4%B8%8D%E4%BD%8F%22%5D%0A%20%20NO%20--%3E%20NOM%5B%22%E5%90%8D%E4%B9%89%E8%B5%84%E4%BA%A7%3A%20%E5%90%8D%E4%B9%89%E5%8D%95%E4%BD%8D%E5%8F%AF%E6%95%B4%E4%BD%93%E7%BC%A9%E6%94%BE%22%5D%0A%20%20NOM%20--%3E%20SUN%5B%22%E5%AE%9E%E9%99%85%E9%85%8D%E7%BD%AE%E5%8F%AF%E4%BB%A5%E4%B8%8D%E5%94%AF%E4%B8%80%22%5D%0A"})]),fallback:o(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[7]||(E[7]=n('<p>与核的关系：复制仍可瘦「给定资产结构下的核」，不会把经济变成完全市场。人多不等于证券多。</p><p>两层价格的机制还改变计价：0 期 \\(q\\) 给资产标价，1 期 \\(p_s\\) 给现货标价。完全市场可以把两者压成一组 Arrow 价格；不完全时没有唯一的状态价格去贴现所有或有束，随机折现因子若存在也不唯一。资产定价课的 \\(p=E[mx]\\) 在完全市场上是均衡的改写；在 GEI 里 \\(m\\) 只能给张成空间里的收益定价，张成之外的要求权没有无套利价格，只有区间。</p><p><span class="marginnote">Magill–Quinzii 把存在、不定与福利收成一套。Geanakoplos 1990 的 <em>JME</em> 导论更短。Geanakoplos–Polemarchakis 1986 的约束无效是福利缺口的原文。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>太阳黑子把外生无关的信号写进信念，不完全市场更容易让太阳黑子成为均衡——下一课。违约、抵押、内生保证金改 \\(A\\) 的有效列。宏观的不完全市场（Bewley）用异质主体加一种债券，是本课的无穷人口特化，主干不把计算写进来。也不要把缺列写成限价簿缺档：这里缺的是或有要求权，不是买卖队列。</p><p><span class="marginnote">常见误区：把核等价读成「人多了市场自动变完全」。实际上人多的作用是复制出竞争，复制瘦的只是「给定资产结构下的核」——缺的状态证券不会因为人口多就从天上掉下来。人多不等于证券多。</span></p><p>实资产局部确定，并不恢复帕累托；只是少了一层名义不定。</p><p>后课默认：GEI 在张成不足时不保证帕累托（甚至不保证约束有效）；名义资产可有实不确定性。完全市场的核等价与两定理不自动继承。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>资产列张不成 \\(\\mathbb{R}^S\\) 时，竞争配置相对于完全市场不必有效。</li><li>现货价格内生于持仓，GEI 一般也不是约束帕累托有效。</li><li>名义资产可有实不定；实资产通常局部确定。</li><li>下一课：外生无关信号能否进入均衡信念。</li><li>出处：Magill and Quinzii, <em>Theory of Incomplete Markets</em>；Geanakoplos, <em>JME</em>, 1990；Geanakoplos and Polemarchakis, 1986。</li></ul>',10))])}const f=l(m,[["render",d]]);export{_ as __pageData,f as default};
